/* Static reference data for the NectarDesigner walkthrough on /software.
 *
 * WHAT IS REAL HERE AND WHAT IS NOT.
 *
 * Real: the species list and their NCBI taxonomy ids, the chassis/promoter/
 * marker compatibility tables, the Dicer-2 product lengths, and which
 * non-target species are worth screening against which pest. That is ordinary
 * domain reference data, the same table a live backend would need.
 *
 * NOT real: transcript counts are plausible round numbers, not counts we
 * verified, and every sequence, score, fold and off-target hit the walkthrough
 * shows is generated by the seeded generator in src/utils/rnaDesign.ts. The
 * component says so on its face and the page says so in prose. Nothing here is
 * a measurement and nothing here is a prediction.
 *
 * The gene names below are a curated pool so a candidate list reads like a
 * screen instead of "Gene 1, Gene 2". They are NOT our target. The real
 * Varroa target is not named anywhere on this wiki pending the IP position
 * (see the holdback note on /software), and this demo does not name it either.
 */

export type TargetClass =
  | "essential"
  | "population-control"
  | "developmental";

export type DeliveryChassis =
  | "s-cerevisiae"
  | "ecoli-ht115"
  | "snodgrassella-alvi";

export type SirnaLength = 19 | 21 | 22 | 24;

export interface Organism {
  id: string;
  commonName: string;
  scientificName: string;
  taxid: number;
  /** Plausible order of magnitude, not a verified count. */
  transcriptCount: number;
  /** false => cannot be screened, and the matrix says so rather than passing it. */
  hasReferenceTranscriptome: boolean;
  kind: "target" | "non-target" | "human";
}

