export function getOrganism(id: string): Organism | undefined {
  return ORGANISMS.find((one) => one.id === id);
}

/** Everything offerable in the safety panel: never a pest, always the others. */
export const SCREENABLE_POOL: Organism[] = [
  ...NON_TARGET_ORGANISMS,
  HUMAN_ORGANISM,
];

/* ---------- which species are worth screening against which pest ---------- */

/* Shared habitat, shared crop system, or a trophic link (predator, parasitoid,
 * pollinator), plus a sentinel for the pest's own order. This is the step
 * Prof. Paul Lam's advice shaped: screen a justified set of representative
 * species rather than everything, because a screen against everything is one
 * nobody can defend or run. */
const PANEL_BY_ORGANISM: Record<string, string[]> = {
  "org-varroa": ["org-apis", "org-bombus", "org-osmia", "org-nasonia"],
  "org-leptinotarsa": [
    "org-coccinella",
    "org-chrysoperla",
    "org-monarch",
    "org-apis",
  ],
  "org-diabrotica": [
    "org-monarch",
    "org-apis",
    "org-bombus",
    "org-coccinella",
  ],
  "org-spodoptera": [
    "org-monarch",
    "org-bombyx",
    "org-coccinella",
    "org-chrysoperla",
  ],
  "org-plutella": [
    "org-bombyx",
    "org-monarch",
    "org-chrysoperla",
    "org-coccinella",
  ],
  "org-bemisia": [
    "org-coccinella",
    "org-chrysoperla",
    "org-nasonia",
    "org-apis",
  ],
  "org-myzus": ["org-coccinella", "org-chrysoperla", "org-nasonia", "org-apis"],
  "org-halyomorpha": [
    "org-nasonia",
    "org-coccinella",
    "org-apis",
    "org-monarch",
  ],
};

const DEFAULT_PANEL = [
  "org-apis",
  "org-bombus",
  "org-monarch",
  "org-coccinella",
];

/** The species the pipeline recommends for this pest. Human is always offered
 * separately and is never dropped from the recommendation silently. */
export function suggestedPanelFor(organismId: string | null): string[] {
  if (!organismId) return DEFAULT_PANEL;
  return PANEL_BY_ORGANISM[organismId] ?? DEFAULT_PANEL;
}

/* ---------- Dicer-2 product length per pest ---------- */

/* The duplex length the pipeline tiles at is a property of the target's own
 * RNAi machinery, so it is derived rather than dialled.
 *
 * VARROA IS THE EXCEPTION, AND DELIBERATELY SO. The canonical arthropod
 * Dicer-2 product is 21 nt, and that is what the other seven pests get. For
 * Varroa we use 24, because our own reading of 54 sample-virus units of
 * Varroa viral small RNA puts 24 nt at the top of the population under both
 * abundance and unique-sequence weighting, with 23 nt behind it. What Dicer
 * cuts and what the mite accumulates are two different questions, and for
 * designing a window it is the second one that matters. The page sets out the
 * analysis; this is the number that comes out of it, and the demo would be
 * contradicting our own result if it said 21 here. */
const LENGTH_BY_ORGANISM: Record<
  string,
  { length: SirnaLength; note: string }
> = {
  "org-varroa": {
    length: 24,
    note: "Our own small RNA analysis puts 24 nt at the top of Varroa's viral population, so windows are scored at 24 rather than the canonical 21.",
  },
  "org-leptinotarsa": {
    length: 21,
    note: "Coleopteran Dicer-2 favours 21 nt duplexes; beetles are the most RNAi-responsive insect order studied.",
  },
  "org-diabrotica": {
    length: 21,
    note: "Coleopteran Dicer-2 favours 21 nt duplexes; beetles are the most RNAi-responsive insect order studied.",
  },
  "org-spodoptera": {
    length: 22,
    note: "Lepidopteran Dicer-2 processing is less efficient; a 22 nt duplex loads more stably.",
  },
  "org-plutella": {
    length: 22,
    note: "Lepidopteran Dicer-2 processing is less efficient; a 22 nt duplex loads more stably.",
  },
  "org-bemisia": {
    length: 21,
    note: "Hemipteran Dicer-2 processing sits at the 21 nt insect default.",
  },
  "org-myzus": {
    length: 19,
    note: "Aphid RNAi response is variable; 19 nt is the better-supported duplex length.",
  },
  "org-halyomorpha": {
    length: 21,
    note: "Hemipteran Dicer-2 processing sits at the 21 nt insect default.",
  },
};

const DEFAULT_LENGTH = {
  length: 21 as SirnaLength,
  note: "No target-specific Dicer data, so the canonical 21 nt Dicer-2 product length is used.",
};

export function lengthForOrganism(organismId: string | null): {
  length: SirnaLength;
  note: string;
} {
  if (!organismId) return DEFAULT_LENGTH;
  return LENGTH_BY_ORGANISM[organismId] ?? DEFAULT_LENGTH;
}

